/**
 * The map "Gully No. 7" as plain data (docs/ART.md).
 *
 * Both the server (collisions, later line of sight) and the client (drawing)
 * read this file, so what you see is exactly what you bump into.
 *
 * Only the BLUE half is written out. The GREEN half is generated by turning it
 * 180° around the centre, so the two halves can never drift apart and the map
 * stays fair.
 */

export type Team = "blue" | "green";
export const TEAMS: readonly Team[] = ["blue", "green"];

export interface Point { x: number; y: number }
export interface Rect { x: number; y: number; w: number; h: number }
export interface Circle { x: number; y: number; r: number }

export type RectKind = "building" | "cart" | "chai";
export type CircleKind = "tree" | "fireplace";
export interface RectObstacle extends Rect { kind: RectKind }
export interface CircleObstacle extends Circle { kind: CircleKind }

/**
 * The layout below is written in DESIGN units (the 2400 × 1350 design board)
 * and scaled up by MAP_SCALE (D55, owner: "make the map feel big"). Blobs keep
 * their size, so a bigger scale = longer trips and wider lanes.
 */
export const MAP_SCALE = 1.5;
const S = MAP_SCALE;
const sRect = <T extends Rect>(r: T): T => ({ ...r, x: r.x * S, y: r.y * S, w: r.w * S, h: r.h * S });
const sCircle = <T extends Circle>(c: T): T => ({ ...c, x: c.x * S, y: c.y * S, r: c.r * S });
const sPoint = (p: Point): Point => ({ x: p.x * S, y: p.y * S });

export const WORLD = { width: 2400 * S, height: 1350 * S } as const;

/** Turn a point / rect / circle 180° around the map centre. */
export const mirrorPoint = (p: Point): Point => ({ x: WORLD.width - p.x, y: WORLD.height - p.y });
export const mirrorRect = <T extends Rect>(r: T): T => ({
  ...r,
  x: WORLD.width - r.x - r.w,
  y: WORLD.height - r.y - r.h,
});
export const mirrorCircle = <T extends Circle>(c: T): T => ({ ...c, ...mirrorPoint(c) });

// ------------------------------------------------ blue half, design units (x < 1200)

const blueRects: RectObstacle[] = ([
  // buildings
  { kind: "building", x: 360, y: 80, w: 260, h: 170 },
  { kind: "building", x: 400, y: 330, w: 90, h: 220 },
  { kind: "building", x: 400, y: 800, w: 90, h: 220 },
  { kind: "building", x: 360, y: 1100, w: 260, h: 170 },
  { kind: "building", x: 560, y: 470, w: 200, h: 110 },
  { kind: "building", x: 560, y: 770, w: 200, h: 110 },
  { kind: "building", x: 840, y: 60, w: 160, h: 200 },
  { kind: "building", x: 850, y: 360, w: 120, h: 150 },
  { kind: "building", x: 850, y: 840, w: 120, h: 150 },
  { kind: "building", x: 840, y: 1090, w: 160, h: 200 },
  { kind: "building", x: 100, y: 120, w: 150, h: 110 },
  { kind: "building", x: 100, y: 1120, w: 150, h: 110 },
  // The run home is a zig-zag, not a straight lane (owner request, D31):
  // three staggered blockers between the middle and the den, openings alternating.
  { kind: "building", x: 960, y: 600, w: 50, h: 150 }, // 1st: block the centre, go round top or bottom
  { kind: "building", x: 640, y: 640, w: 120, h: 130 }, // 2nd: juts up from the lower block, squeezes the lane
  { kind: "building", x: 250, y: 560, w: 60, h: 230 }, // 3rd: "goalkeeper" wall in front of the den
  // carts (thelas)
  { kind: "cart", x: 560, y: 300, w: 70, h: 36 },
  { kind: "cart", x: 240, y: 950, w: 70, h: 36 },
  { kind: "cart", x: 410, y: 657, w: 70, h: 36 },
  { kind: "cart", x: 690, y: 1000, w: 70, h: 36 },
  // chai stalls
  { kind: "chai", x: 680, y: 1180, w: 100, h: 56 },
  { kind: "chai", x: 130, y: 300, w: 100, h: 56 },
] as RectObstacle[]).map(sRect);

// Rule: gaps between obstacles are either closed or at least 44 (a blob) wide,
// so nobody gets wedged. shared/test/map.test.ts checks this.
const blueCircles: CircleObstacle[] = ([
  { kind: "tree", x: 160, y: 900, r: 32 },
  { kind: "tree", x: 580, y: 1010, r: 32 },
  { kind: "tree", x: 700, y: 385, r: 32 },
  { kind: "tree", x: 1080, y: 250, r: 32 },
  { kind: "tree", x: 1100, y: 1050, r: 32 },
  { kind: "tree", x: 200, y: 450, r: 32 },
  { kind: "fireplace", x: 720, y: 230, r: 40 },
] as CircleObstacle[]).map(sCircle);

/** Like a goal: flat against the end line, centred, nothing behind it. */
const blueDen: Rect = sRect({ x: 0, y: 535, w: 170, h: 280 });

/** Spawn spots inside the den: 3 columns × 4 rows = 12 (max team is 10). */
const blueSpawns: Point[] = [];
for (const y of [575, 635, 695, 755]) for (const x of [40, 85, 130]) blueSpawns.push(sPoint({ x, y }));

// ---------------------------------------------------------------- the full map

export const MAP = {
  ...WORLD,
  /** x < halfLine is the Blue half; x >= halfLine is the Green half. */
  halfLine: WORLD.width / 2,
  dens: { blue: blueDen, green: mirrorRect(blueDen) } as Record<Team, Rect>,
  middleZone: { x: WORLD.width / 2, y: WORLD.height / 2, r: 150 * S } as Circle,
  spawns: { blue: blueSpawns, green: blueSpawns.map(mirrorPoint) } as Record<Team, Point[]>,
  rects: [...blueRects, ...blueRects.map(mirrorRect)],
  circles: [...blueCircles, ...blueCircles.map(mirrorCircle)],
};

/** Which half a position is on. */
export function halfAt(x: number): Team {
  return x < MAP.halfLine ? "blue" : "green";
}

/** True if a circle of radius `r` at (x, y) overlaps any obstacle or leaves the world. */
export function isBlocked(x: number, y: number, r: number): boolean {
  if (x < r || y < r || x > MAP.width - r || y > MAP.height - r) return true;
  for (const o of MAP.rects) {
    const cx = Math.max(o.x, Math.min(x, o.x + o.w));
    const cy = Math.max(o.y, Math.min(y, o.y + o.h));
    const dx = x - cx;
    const dy = y - cy;
    if (dx * dx + dy * dy < r * r) return true;
  }
  for (const c of MAP.circles) {
    const dx = x - c.x;
    const dy = y - c.y;
    const min = r + c.r;
    if (dx * dx + dy * dy < min * min) return true;
  }
  return false;
}
